import {WASTE_STRUCTURES,wasteCapacity,wasteActive,wastePower} from './utilities.js?v=hospital-patients-1';
export function wasteFacilityData(city){return city.tiles.flatMap((tile,index)=>{const definition=WASTE_STRUCTURES[tile.type];if(!definition)return[];const capacity=wasteCapacity(city,tile),newCapacity=wasteCapacity(city,{...tile,age:0}),ready=wasteActive(city,tile);return[{tile:index,name:definition.name,x:tile.x,y:tile.y,age:tile.age,capacity,newCapacity,efficiency:newCapacity?capacity/newCapacity:0,nextYear:wasteCapacity(city,{...tile,age:tile.age+12}),processed:(tile.burnedLastMonth||0)+(tile.recycledLastMonth||0),power:wastePower(tile),upkeep:definition.upkeep,rebuildCost:definition.cost,ready,status:ready?'Ready':!tile.roadIds.length?'No road access':city.finance.roadCondition<=20?'Roads unusable':'No electricity'}];}).sort((a,b)=>a.efficiency-b.efficiency||b.age-a.age||a.tile-b.tile);}
export function wasteFacilityReport(city){const rows=wasteFacilityData(city),fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:1});return `<h3>Garbage facility maintenance</h3><p>Facilities with the greatest age-related capacity loss appear first. Capacity is potential processing per month; the last processed amount also depends on reachable garbage, competing facilities and recycling eligibility.</p><div class="table-scroll" style="max-height:360px;overflow:auto"><table><thead><tr><th>Facility</th><th>Operation / age</th><th>Capacity / new</th><th>In 12 months</th><th>Last processed</th><th>Upkeep / rebuild</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name} · ${r.x+1}, ${r.y+1}<br><button data-waste-inspect="${r.tile}" aria-label="Inspect ${r.name} at ${r.x+1}, ${r.y+1}">Inspect</button></td><td>${r.status}<br>${fmt(r.age/12)} years</td><td>${fmt(r.capacity)} / ${fmt(r.newCapacity)} (${fmt(r.efficiency*100)}%)</td><td>${fmt(r.nextYear)}</td><td>${fmt(r.processed)}</td><td>§${fmt(r.upkeep)}/month · §${fmt(r.rebuildCost)}</td></tr>`).join('')||'<tr><td colspan="6">No recycling centers or incinerators yet.</td></tr>'}</tbody></table></div><p>The 12-month figure isolates normal aging with today’s ordinance settings. It assumes the facility survives; it does not predict garbage volumes or road and power changes. Recycling figures include Trash Presort when enabled. Add replacement capacity before demolishing an old facility; rebuild costs exclude demolition. Waste-to-energy electricity depends on actual garbage burned, so falling processing capacity can also reduce power supply. Landfill storage is listed separately below.</p>`;}
export function installWasteFacilityLinks(city,visit,root=document){root.querySelectorAll('[data-waste-inspect]').forEach(button=>{button.onclick=()=>{const index=Number(button.getAttribute('data-waste-inspect')),tile=city.tiles[index];if(Number.isInteger(index)&&tile&&WASTE_STRUCTURES[tile.type])visit({x:tile.x,y:tile.y});};});}
